def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]
    total_opp_c = 0
    total_my_c = 0
    total_my_d = 0
    for a, b in history:
        if b == 'C':
            total_opp_c += 1
        if a == 'C':
            total_my_c += 1
        else:
            total_my_d += 1
    total_opp_d = n - total_opp_c
    coop_rate = total_opp_c / n

    recent = history[-12:]
    recent_opp_c = 0
    recent_my_c = 0
    for a, b in recent:
        if b == 'C':
            recent_opp_c += 1
        if a == 'C':
            recent_my_c += 1
    recent_opp_d = len(recent) - recent_opp_c
    recent_my_d = len(recent) - recent_my_c

    after_c_c = 0
    after_c_d = 0
    after_d_c = 0
    after_d_d = 0
    recent_after_d_c = 0
    recent_after_d_d = 0
    st = [0, 0, 0, 0]
    sc = [0, 0, 0, 0]
    start_recent = n - 25
    if start_recent < 0:
        start_recent = 0

    for i in range(n - 1):
        a, b = history[i]
        nb = history[i + 1][1]
        mi = 1 if a == 'D' else 0
        oi = 1 if b == 'D' else 0
        idx = mi * 2 + oi
        st[idx] += 1
        if nb == 'C':
            sc[idx] += 1
        if a == 'C':
            if nb == 'C':
                after_c_c += 1
            else:
                after_c_d += 1
        else:
            if nb == 'C':
                after_d_c += 1
            else:
                after_d_d += 1
            if i >= start_recent:
                if nb == 'C':
                    recent_after_d_c += 1
                else:
                    recent_after_d_d += 1

    after_c_total = after_c_c + after_c_d
    after_d_total = after_d_c + after_d_d
    if after_c_total > 0:
        pC = after_c_c / after_c_total
    else:
        pC = coop_rate

    if after_d_total >= 3:
        pD = after_d_c / after_d_total
    else:
        pD = None

    recent_after_d_total = recent_after_d_c + recent_after_d_d
    if recent_after_d_total >= 2:
        recent_pD = recent_after_d_c / recent_after_d_total
    elif pD is not None:
        recent_pD = pD
    else:
        recent_pD = None

    exploit = False
    if total_opp_d == 0 and after_d_total >= 4:
        exploit = True
    elif n >= 20 and pD is not None and recent_pD is not None:
        if pD >= 0.60 and recent_pD >= 0.55 and recent_opp_c >= 7 and coop_rate > 0.55:
            exploit = True
    if exploit and (recent_opp_d >= 4 or coop_rate < 0.50):
        exploit = False

    idx_last = (1 if my_last == 'D' else 0) * 2 + (1 if opp_last == 'D' else 0)
    if st[idx_last] >= 2:
        q = sc[idx_last] / st[idx_last]
    elif my_last == 'C':
        q = pC
    else:
        if pD is not None:
            q = pD
        elif total_opp_d == 0:
            q = pC
        else:
            q = max(0.0, pC - 0.45)

    if n == 98:
        if st[0] >= 2:
            s00 = sc[0] / st[0]
        else:
            s00 = pC
        if st[1] >= 2:
            s01 = sc[1] / st[1]
        else:
            s01 = pC * 0.90
        if st[2] >= 2:
            s10 = sc[2] / st[2]
        else:
            if pD is not None:
                s10 = pD
            elif total_opp_d == 0:
                s10 = pC
            else:
                s10 = max(0.0, pC - 0.45)
        if st[3] >= 2:
            s11 = sc[3] / st[3]
        else:
            if pD is not None:
                s11 = pD
            elif total_opp_d == 0:
                s11 = pC
            else:
                s11 = max(0.0, pC - 0.55)
        exp_c = q * s00 + (1.0 - q) * s01
        exp_d = q * s10 + (1.0 - q) * s11
        if q < 0.25 and recent_opp_c <= 4:
            return 'D'
        if exp_c - exp_d >= (1.0 + q) / 4.0:
            return 'C'
        return 'D'

    if n >= 96 and n >= 2 and opp_last == 'D' and history[-2][0] == 'C' and history[-2][1] == 'C':
        return 'D'

    if not exploit and total_opp_d == 0 and after_d_total < 4:
        if my_last == 'D' and opp_last == 'C':
            return 'C'
        if n >= 10:
            return 'D'
        return 'C'

    if exploit:
        if q >= 0.58:
            return 'D'
        if my_last == 'D' and recent_opp_d >= 3:
            return 'D'
        return 'C'

    if n >= 8 and (coop_rate < 0.35 or recent_opp_c <= 2):
        return 'D'
    if total_opp_d == n and n >= 2:
        return 'D'

    if opp_last == 'D':
        if total_opp_d >= 2 and total_opp_d * 2 >= n and n <= 6:
            return 'D'
        if my_last == 'D':
            if recent_opp_d >= 5:
                return 'D'
            return 'C'
        if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
            if recent_opp_d >= 3 or coop_rate < 0.45:
                return 'D'
            return 'C'
        if recent_opp_d >= 3 or coop_rate < 0.50:
            return 'D'
        if recent_opp_d >= 2:
            return 'D'
        if recent_my_c >= 6:
            return 'C'
        return 'D'
    else:
        if recent_opp_d >= 5 and recent_my_d <= 2:
            return 'D'
        return 'C'
